  const [filter, setFilter] = useState('all');

  function handleAdd() {
    const trimmed = name.trim();
    if (trimmed === '') {
      setHint('商品名称不能为空');
      return;
    }
    setItems([
      ...items,
      { id: Date.now() + Math.random(), name: trimmed, quantity: 1, purchased: false },
