import React, { useState } from 'react';
import './styles.css';

export default function App() {
  const [name, setName] = useState('');
  const [items, setItems] = useState([]);
  const [hint, setHint] = useState('');
  const [filter, setFilter] = useState('all');

  function handleAdd() {
    const trimmed = name.trim();
    if (trimmed === '') {
      setHint('商品名称不能为空');
      return;
    }
    setItems([
      ...items,
      { id: Date.now() + Math.random(), name: trimmed, quantity: 1, purchased: false },
    ]);
    setName('');
    setHint('');
  }

  function changeQuantity(id, delta) {
    setItems((prev) =>
      prev.map((item) =>
        item.id === id
          ? { ...item, quantity: Math.max(1, item.quantity + delta) }
          : item
      )
    );
  }

  function togglePurchased(id) {
    setItems((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, purchased: !item.purchased } : item
      )
    );
  }

  function removeItem(id) {
    setItems((prev) => prev.filter((item) => item.id !== id));
  }

  const visibleItems = items.filter((item) => {
    if (filter === 'pending') return !item.purchased;
    if (filter === 'purchased') return item.purchased;
    return true;
  });

  const kindCount = items.length;
  const pendingTotal = items
    .filter((item) => !item.purchased)
    .reduce((sum, item) => sum + item.quantity, 0);

  return (
    <main>
      <h1>购物清单</h1>
      <div className="add-row">
        <input
          data-testid="item-name-input"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="商品名称"
        />
        <button data-testid="add-button" onClick={handleAdd}>添加</button>
      </div>
      {hint && <p data-testid="blank-hint" className="hint">{hint}</p>}
      <div className="stats-row">
        <span className="stat">商品种类数：<span data-testid="stats-kind-count">{kindCount}</span></span>
        <span className="stat">待购买总件数：<span data-testid="stats-pending-total">{pendingTotal}</span></span>
      </div>
      <div className="filter-row">
        <button data-testid="filter-all" onClick={() => setFilter('all')}>全部</button>
        <button data-testid="filter-pending" onClick={() => setFilter('pending')}>待购买</button>
        <button data-testid="filter-purchased" onClick={() => setFilter('purchased')}>已购买</button>
      </div>
      <ul className="item-list">
        {visibleItems.map((item) => (
          <li key={item.id} className="item">
            <span data-testid="item-name">{item.name}</span>
            <span data-testid="item-status" className="status">
              {item.purchased ? '已购买' : '待购买'}
            </span>
            <span className="quantity-controls">
              <button data-testid="item-decrease" aria-label={`减少 ${item.name} 的数量`} onClick={() => changeQuantity(item.id, -1)}>减少</button>
              <span data-testid="item-quantity">{item.quantity}</span>
              <button data-testid="item-increase" aria-label={`增加 ${item.name} 的数量`} onClick={() => changeQuantity(item.id, 1)}>增加</button>
            </span>
            <button data-testid="item-toggle" aria-label={`切换 ${item.name} 的购买状态`} onClick={() => togglePurchased(item.id)}>切换状态</button>
            <button data-testid="item-delete" aria-label={`删除 ${item.name}`} onClick={() => removeItem(item.id)}>删除</button>
          </li>
        ))}
      </ul>
    </main>
  );
}

